using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool(Name = "get_weather")]
    [System.ComponentModel.Description("Get current weather for a location by latitude and longitude.")]
    public static async Task<string> GetWeatherAsync(
        IHttpClientFactory httpClientFactory,
        [System.ComponentModel.Description("Latitude of the location")] double latitude,
        [System.ComponentModel.Description("Longitude of the location")] double longitude)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true";
        var response = await client.GetFromJsonAsync<WeatherResponse>(url);

        if (response?.CurrentWeather is null)
            return "Unable to retrieve weather data.";

        var w = response.CurrentWeather;
        return $"Temperature: {w.Temperature}°C, Wind: {w.WindSpeed} km/h, Direction: {w.WindDirection}°";
    }
}

public record WeatherResponse(
    [property: JsonPropertyName("current_weather")] CurrentWeather? CurrentWeather);

public record CurrentWeather(
    [property: JsonPropertyName("temperature")] double Temperature,
    [property: JsonPropertyName("windspeed")] double WindSpeed,
    [property: JsonPropertyName("winddirection")] double WindDirection);

